import React, { useState, useEffect, useRef, useMemo, useCallback } from "react";
import { Clock3, Plus, Trash2, ChevronLeft, ChevronRight } from "lucide-react";
import { supabase } from "./supabaseClient";

// TODO: paste your original base64 logo string back in here.
// Replaced with a placeholder to avoid transcription risk on the ~9,000-character
// base64 blob (this is what corrupted the file on the first attempt).
const KRAKEN_LOGO = "data:image/png;base64,";

// ---------- tokens ----------
const COLORS = {
  bg: "#0E0F10",
  bgLocal: "#22252A",
  panel: "#1A1C1F",
  panelAlt: "#212327",
  border: "#2E3136",
  borderSoft: "#25272B",
  amber: "#A56CF2",
  amberSoft: "#4A3170",
  accent: "#6C8CF5",
  accentSoft: "#2B3B6B",
  red: "#FF5A66",
  redSoft: "#5A2126",
  textPrimary: "#ECE8DE",
  textMuted: "#8B9099",
  textFaint: "#5C6066",
};

const FONT_IMPORT = `@import url('https://fonts.googleapis.com/css2?family=Oswald:wght@500;600;700&family=JetBrains+Mono:wght@400;500;600&display=swap');`;

const STORAGE_PREFIX = "torn-war-room-v1";
const TOTAL_SLOTS = 48; // 30-min increments over 24h
const DAY_COUNT = 7;

// ---------- helpers ----------
function pad2(n) {
  return String(n).padStart(2, "0");
}
function dateKeyFor(d) {
  return `${d.getUTCFullYear()}-${pad2(d.getUTCMonth() + 1)}-${pad2(d.getUTCDate())}`;
}
function getDays(count) {
  const now = new Date();
  const start = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()));
  const out = [];
  for (let i = 0; i < count; i++) {
    const d = new Date(start);
    d.setUTCDate(start.getUTCDate() + i);
    out.push(d);
  }
  return out;
}
function slotTime(idx) {
  const h = Math.floor(idx / 2);
  const m = idx % 2 === 0 ? "00" : "30";
  return `${pad2(h)}:${m}`;
}
const WEEKDAY = ["SUN", "MON", "TUE", "WED", "THU", "FRI", "SAT"];
const MONTH = ["JAN","FEB","MAR","APR","MAY","JUN","JUL","AUG","SEP","OCT","NOV","DEC"];
function dayLabel(d) {
  return { top: WEEKDAY[d.getUTCDay()], bottom: `${d.getUTCDate()} ${MONTH[d.getUTCMonth()]}` };
}
function mixHex(hex1, hex2, t) {
  const a = parseInt(hex1.slice(1), 16), b = parseInt(hex2.slice(1), 16);
  const ar = (a >> 16) & 255, ag = (a >> 8) & 255, ab = a & 255;
  const br = (b >> 16) & 255, bg = (b >> 8) & 255, bb = b & 255;
  const r = Math.round(ar + (br - ar) * t);
  const g = Math.round(ag + (bg - ag) * t);
  const bl = Math.round(ab + (bb - ab) * t);
  return `rgb(${r}, ${g}, ${bl})`;
}

// Normalizes a stored day entry to { slots: number[], notes: { [idx]: string } }.
// Also accepts the old bare-array format so nothing breaks if old data is present.
function normalizeDay(raw) {
  if (Array.isArray(raw)) return { slots: raw, notes: {} };
  if (raw && typeof raw === "object") return { slots: raw.slots || [], notes: raw.notes || {} };
  return { slots: [], notes: {} };
}

// Fixed UTC-offset options (not full IANA/DST-aware timezones - deliberately simple).
const TZ_OPTIONS = [
  -720, -660, -600, -570, -540, -480, -420, -360, -300, -240, -210, -180, -120, -60, 0,
  60, 120, 180, 210, 240, 270, 300, 330, 345, 360, 390, 420, 480, 525, 540, 570, 600, 630, 660, 720, 765, 780, 840,
].map((m) => ({
  minutes: m,
  label: `UTC${m === 0 ? "\u00B10" : (m > 0 ? "+" : "\u2212") + pad2(Math.floor(Math.abs(m) / 60)) + ":" + pad2(Math.abs(m) % 60)}`,
}));

function closestTzOption(minutes) {
  let best = TZ_OPTIONS[0];
  let bestDiff = Infinity;
  for (const opt of TZ_OPTIONS) {
    const diff = Math.abs(opt.minutes - minutes);
    if (diff < bestDiff) { bestDiff = diff; best = opt; }
  }
  return best.minutes;
}

// Converts a TCT slot index (0-47, on the currently viewed TCT day) into a label
// in the given UTC offset. Slots don't remap across the day grid - only the label changes -
// so a +1/-1 day marker is shown when the local time crosses midnight relative to TCT.
function localLabel(idx, offsetMinutes) {
  const totalLocalMin = idx * 30 + offsetMinutes;
  const dayShift = Math.floor(totalLocalMin / 1440);
  const minOfDay = ((totalLocalMin % 1440) + 1440) % 1440;
  const h = Math.floor(minOfDay / 60);
  const m = minOfDay % 60;
  return { time: `${pad2(h)}:${pad2(m)}`, dayShift };
}

// Battle stats brackets, chosen at check-in. Each person's name renders in
// their bracket color everywhere it appears in the grid/roster.
const BRACKETS = [
  { key: "blue", label: "Blue", range: "0 - 1m", bg: "#3B82F6", text: "#FFFFFF" },
  { key: "green", label: "Green", range: "1m - 10m", bg: "#22C55E", text: "#0B1F13" },
  { key: "yellow", label: "Yellow", range: "10m - 100m", bg: "#EAB308", text: "#231C02" },
  { key: "orange", label: "Orange", range: "100m - 500m", bg: "#F97316", text: "#241000" },
  { key: "red", label: "Red", range: "500m - 1b", bg: "#EF4444", text: "#FFFFFF" },
  { key: "burgundy", label: "Burgundy", range: "1b+", bg: "#7C2D3E", text: "#FFFFFF" },
];
const BRACKET_BY_KEY = Object.fromEntries(BRACKETS.map((b) => [b.key, b]));
const UNSET_BRACKET = { key: null, label: "Unranked", range: "", bg: "#3A3D42", text: "#C7CBD1" };
function bracketFor(key) {
  return (key && BRACKET_BY_KEY[key]) || UNSET_BRACKET;
}

export default function App() {
  const days = useMemo(() => getDays(DAY_COUNT), []);
  const [dayIdx, setDayIdx] = useState(0);
  const [name, setName] = useState(null);
  const [nameInput, setNameInput] = useState("");
  const [nameLoading, setNameLoading] = useState(true);
  const [myBracket, setMyBracket] = useState(null); // bracket key, or null until chosen
  const [bracketDraft, setBracketDraft] = useState(null); // selection in progress on entry screen
  const [editingBracket, setEditingBracket] = useState(false); // header re-pick panel open?

  // { [username]: { [dateKey]: number[] } }
  const [allAvail, setAllAvail] = useState({});
  const [loading, setLoading] = useState(true);
 const [saveFailed, setSaveFailed] = useState(false);
  const [saveErrorDetail, setSaveErrorDetail] = useState("");
  const [syncFailed, setSyncFailed] = useState(false);
  const [now, setNow] = useState(new Date());
  const [rangeStart, setRangeStart] = useState(16); // 08:00
  const [rangeEnd, setRangeEnd] = useState(20); // 10:00
  const [isCoarsePointer, setIsCoarsePointer] = useState(false);
  const [tzOffset, setTzOffset] = useState(0); // minutes from UTC, defaults to TCT
  const [viewMode, setViewMode] = useState("tct"); // 'tct' | 'local' - controls grid labels + theme
  const [noteEditor, setNoteEditor] = useState(null); // { idx, text } | null

  const dragRef = useRef({ active: false, mode: "add" });
  const saveTimerRef = useRef(null);
  const nowRowRef = useRef(null);

  // clock
  useEffect(() => {
    const t = setInterval(() => setNow(new Date()), 15000);
    return () => clearInterval(t);
  }, []);

  useEffect(() => {
    if (typeof window !== "undefined" && window.matchMedia) {
      setIsCoarsePointer(window.matchMedia("(pointer: coarse)").matches);
    }
  }, []);

  // load identity (name + bracket) - personal to this browser, so localStorage
  useEffect(() => {
    try {
      const raw = localStorage.getItem(`${STORAGE_PREFIX}:me`);
      if (raw) {
        const parsed = JSON.parse(raw);
        if (parsed && typeof parsed === "object" && parsed.name) {
          setName(parsed.name);
          if (parsed.bracket) setMyBracket(parsed.bracket);
        }
      }
    } catch (e) {
      // malformed or inaccessible localStorage - just start fresh
    } finally {
      setNameLoading(false);
    }
  }, []);

  // load timezone/view-mode preference (personal, not shared) - falls back to the
  // browser's own offset (rounded to the nearest supported option) the first time
  useEffect(() => {
    try {
      const raw = localStorage.getItem(`${STORAGE_PREFIX}:tzprefs`);
      if (raw) {
        const parsed = JSON.parse(raw);
        if (typeof parsed.tzOffset === "number") setTzOffset(parsed.tzOffset);
        if (parsed.viewMode === "tct" || parsed.viewMode === "local") setViewMode(parsed.viewMode);
        return;
      }
    } catch (e) {
      // nothing saved yet, or malformed - fall through to browser default
    }
    setTzOffset(closestTzOption(-new Date().getTimezoneOffset()));
  }, []);

  const saveTzPrefs = useCallback((nextTzOffset, nextViewMode) => {
    try {
      localStorage.setItem(`${STORAGE_PREFIX}:tzprefs`, JSON.stringify({ tzOffset: nextTzOffset, viewMode: nextViewMode }));
    } catch (e) {
      // non-fatal - worst case the preference doesn't persist across visits
    }
  }, []);

  const myBracketRef = useRef(myBracket);
  useEffect(() => { myBracketRef.current = myBracket; }, [myBracket]);

  const loadAll = useCallback(async (preserveName) => {
    try {
      const { data, error } = await supabase
        .from("availability")
        .select("username, bracket, date_key, slots, notes");
      if (error) throw error;
      const fetched = {};
      (data || []).forEach((row) => {
        if (!fetched[row.username]) fetched[row.username] = {};
        if (row.bracket) fetched[row.username]._bracket = row.bracket;
        fetched[row.username][row.date_key] = { slots: row.slots || [], notes: row.notes || {} };
      });
      setAllAvail((prev) => {
        // merge rather than replace, and always read "prev" fresh (avoids
        // ever acting on a stale snapshot from an old render)
        const next = { ...prev, ...fetched };
        if (preserveName && prev[preserveName]) {
          next[preserveName] = prev[preserveName];
        }
        return next;
      });
      setSyncFailed(false);
    } catch (e) {
      console.error("load failed", e);
      setSyncFailed(true);
    } finally {
      setLoading(false);
    }
  }, []); // stable identity - safe to call from a long-lived interval

  useEffect(() => {
    loadAll();
    if (!name) return;
    // sync 5s after the user's last interaction (not on a fixed clock) -
    // avoids syncing mid-drag/mid-tap and keeps calls down when someone
    // is actively using the room
    let idleTimer;
    const triggerIdleSync = () => {
      loadAll(name);
      idleTimer = setTimeout(triggerIdleSync, 5000);
    };
    const resetIdleTimer = () => {
      clearTimeout(idleTimer);
      idleTimer = setTimeout(triggerIdleSync, 5000);
    };
    resetIdleTimer();
    const events = ["pointerdown", "keydown", "touchstart"];
    events.forEach((ev) => window.addEventListener(ev, resetIdleTimer));
    return () => {
      clearTimeout(idleTimer);
      events.forEach((ev) => window.removeEventListener(ev, resetIdleTimer));
    };
  }, [name, loadAll]);

  const confirmName = async () => {
    const trimmed = nameInput.trim();
    if (!trimmed || !bracketDraft) return;
    setName(trimmed);
    setMyBracket(bracketDraft);
    try {
      localStorage.setItem(`${STORAGE_PREFIX}:me`, JSON.stringify({ name: trimmed, bracket: bracketDraft }));
    } catch (e) {
      console.error("could not save identity locally", e);
    }
    // create today's row so this person (and their bracket color) shows up for everyone else
    setAllAvail((prev) => {
      const userMap = { ...(prev[trimmed] || {}), _bracket: bracketDraft };
      userMap[currentDateKey] = normalizeDay(userMap[currentDateKey]);
      return { ...prev, [trimmed]: userMap };
    });
    scheduleSave(trimmed, currentDateKey, normalizeDay(undefined));
  };

  const changeBracket = (key) => {
    setMyBracket(key);
    setEditingBracket(false);
    try {
      localStorage.setItem(`${STORAGE_PREFIX}:me`, JSON.stringify({ name, bracket: key }));
    } catch (e) {
      console.error("could not save bracket locally", e);
    }
    setAllAvail((prev) => {
      const userMap = { ...(prev[name] || {}), _bracket: key };
      return { ...prev, [name]: userMap };
    });
    // update every existing row for this person so the color's consistent everywhere,
    // then make sure today's row exists even if they had none yet
    supabase
      .from("availability")
      .update({ bracket: key })
      .eq("username", name)
      .then(({ error }) => { if (error) console.error("could not update bracket", error); });
    scheduleSave(name, currentDateKey, normalizeDay(allAvail[name] && allAvail[name][currentDateKey]));
  };

  const saveMine = useCallback(async (uname, dateKey, dayData, attempt = 0) => {
    try {
      const { error } = await supabase.from("availability").upsert(
    {
          username: uname,
          date_key: dateKey,
          slots: dayData.slots,
          notes: dayData.notes,
          bracket: myBracketRef.current || null,
        },
        { onConflict: "username,date_key" }
      );
      if (error) throw error;
      setSaveFailed(false);
      setSaveErrorDetail("");
    } catch (e) {
      console.error("save failed", e);
      setSaveErrorDetail((e && e.message) ? e.message : JSON.stringify(e));
      if (attempt < 2) {
        // brief backoff in case it was a transient rate limit, before surfacing an error
        setTimeout(() => saveMine(uname, dateKey, dayData, attempt + 1), 1500 * (attempt + 1));
      } else {
        setSaveFailed(true);
      }
    }
  }, []);

  const scheduleSave = useCallback((uname, dateKey, dayData) => {
    if (saveTimerRef.current) clearTimeout(saveTimerRef.current);
    saveTimerRef.current = setTimeout(() => saveMine(uname, dateKey, dayData), 500);
  }, [saveMine]);

  const currentDateKey = dateKeyFor(days[dayIdx]);
  const mySet = useMemo(() => {
    return new Set(normalizeDay(allAvail[name] && allAvail[name][currentDateKey]).slots);
  }, [allAvail, name, currentDateKey]);

  const applySlot = (uname, dateKey, idx, on) => {
    setAllAvail((prev) => {
      const userMap = { ...(prev[uname] || {}) };
      const day = normalizeDay(userMap[dateKey]);
      const set = new Set(day.slots);
      const notes = { ...day.notes };
      if (on) set.add(idx);
      else { set.delete(idx); delete notes[idx]; }
      const newDay = { slots: Array.from(set).sort((a, b) => a - b), notes };
      userMap[dateKey] = newDay;
      const next = { ...prev, [uname]: userMap };
      scheduleSave(uname, dateKey, newDay);
      return next;
    });
  };

  const applyRange = (uname, dateKey, startIdx, endIdx, on) => {
    setAllAvail((prev) => {
      const userMap = { ...(prev[uname] || {}) };
      const day = normalizeDay(userMap[dateKey]);
      const set = new Set(day.slots);
      const notes = { ...day.notes };
      let lo = Math.min(startIdx, endIdx), hi = Math.max(startIdx, endIdx);
      // never let "mark free" reach into the past on today's date
      if (on && dateKey === dateKeyFor(days[0])) {
        lo = Math.max(lo, nowSlot);
      }
      for (let i = lo; i < hi; i++) { if (on) set.add(i); else { set.delete(i); delete notes[i]; } }
      const newDay = { slots: Array.from(set).sort((a, b) => a - b), notes };
      userMap[dateKey] = newDay;
      const next = { ...prev, [uname]: userMap };
      scheduleSave(uname, dateKey, newDay);
      return next;
    });
  };

  const clearDay = (uname, dateKey) => {
    setAllAvail((prev) => {
      const userMap = { ...(prev[uname] || {}) };
      const newDay = { slots: [], notes: {} };
      userMap[dateKey] = newDay;
      const next = { ...prev, [uname]: userMap };
      scheduleSave(uname, dateKey, newDay);
      return next;
    });
  };

  const setNote = (uname, dateKey, idx, text) => {
    setAllAvail((prev) => {
      const userMap = { ...(prev[uname] || {}) };
      const day = normalizeDay(userMap[dateKey]);
      const notes = { ...day.notes };
      const trimmed = text.trim();
      if (trimmed) notes[idx] = trimmed.slice(0, 140);
      else delete notes[idx];
      const newDay = { slots: day.slots, notes };
      userMap[dateKey] = newDay;
      const next = { ...prev, [uname]: userMap };
      scheduleSave(uname, dateKey, newDay);
      return next;
    });
  };

  const roster = useMemo(() => Object.keys(allAvail).sort(), [allAvail]);
  const totalOperatives = Math.max(roster.length, name && !roster.includes(name) ? 1 : 0);

  const counts = useMemo(() => {
    const arr = new Array(TOTAL_SLOTS).fill(0);
    const who = Array.from({ length: TOTAL_SLOTS }, () => []);
    const notesByIdx = Array.from({ length: TOTAL_SLOTS }, () => ({}));
    roster.forEach((u) => {
      const day = normalizeDay(allAvail[u] && allAvail[u][currentDateKey]);
      day.slots.forEach((i) => {
        arr[i] += 1;
        who[i].push(u);
        if (day.notes[i]) notesByIdx[i][u] = day.notes[i];
      });
    });
    return { arr, who, notesByIdx };
  }, [allAvail, roster, currentDateKey]);

  const isToday = dayIdx === 0;
  const nowSlot = Math.floor((now.getUTCHours() * 60 + now.getUTCMinutes()) / 30);

  useEffect(() => {
    if (isToday && rangeStart < nowSlot) {
      setRangeStart(nowSlot);
      if (rangeEnd <= nowSlot) setRangeEnd(Math.min(nowSlot + 2, TOTAL_SLOTS));
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isToday, nowSlot]);

  useEffect(() => {
    if (!name) return;
    const t = setTimeout(() => {
      nowRowRef.current?.scrollIntoView({ block: "center", behavior: "auto" });
    }, 120);
    return () => clearTimeout(t);
  }, [name]);

  const onCellClick = (idx) => {
    // native click already ignores taps that turned into a scroll,
    // so no artificial delay is needed here. Mouse users are handled
    // by onPointerDown/onPointerEnter below instead, so guard here.
    if (!name || !isCoarsePointer) return;
    applySlot(name, currentDateKey, idx, !mySet.has(idx));
  };
  const onCellDown = (idx) => {
    if (!name || isCoarsePointer) return;
    const turningOn = !mySet.has(idx);
    dragRef.current = { active: true, mode: turningOn ? "add" : "remove" };
    applySlot(name, currentDateKey, idx, turningOn);
  };
  const onCellEnter = (idx) => {
    if (!name || isCoarsePointer || !dragRef.current.active) return;
    applySlot(name, currentDateKey, idx, dragRef.current.mode === "add");
  };
  useEffect(() => {
    const up = () => { dragRef.current.active = false; };
    window.addEventListener("pointerup", up);
    return () => window.removeEventListener("pointerup", up);
  }, []);

  if (nameLoading) {
    return <div style={{ background: COLORS.bg, minHeight: "100vh" }} />;
  }

  if (!name) {
    return (
      <div style={{ background: COLORS.bg, minHeight: "100vh", color: COLORS.textPrimary, fontFamily: "'JetBrains Mono', monospace" }} className="flex items-center justify-center p-6">
        <style>{FONT_IMPORT}</style>
        <div style={{ background: COLORS.panel, border: `1px solid ${COLORS.border}` }} className="w-full max-w-sm rounded-sm p-6">
          <div className="flex items-center gap-2 mb-1" style={{ color: COLORS.amber }}>
            <img src={KRAKEN_LOGO} alt="Kraken" style={{ width: 22, height: 22, borderRadius: "50%" }} />
            <span style={{ fontFamily: "'Oswald', sans-serif", letterSpacing: "0.08em" }} className="uppercase text-sm font-semibold">Kraken's War Room Access</span>
          </div>
          <p style={{ color: COLORS.textMuted }} className="text-xs mb-4">Enter your Torn name so your faction can see your slots.</p>
          <input
            autoFocus
            value={nameInput}
            onChange={(e) => setNameInput(e.target.value)}
            onKeyDown={(e) => e.key === "Enter" && bracketDraft && confirmName()}
            placeholder="e.g. Ranked_Bandit"
            style={{ background: COLORS.panelAlt, border: `1px solid ${COLORS.border}`, color: COLORS.textPrimary }}
            className="w-full rounded-sm px-3 py-2 text-sm mb-3 outline-none"
          />
          <p style={{ color: COLORS.textMuted }} className="text-xs mb-2">Your battle stats bracket — shown next to your name on the grid.</p>
          <div className="grid grid-cols-2 gap-1.5 mb-4">
            {BRACKETS.map((b) => {
              const selected = bracketDraft === b.key;
              return (
                <button
                  key={b.key}
                  onClick={() => setBracketDraft(b.key)}
                  style={{
                    background: b.bg,
                    color: b.text,
                    border: selected ? "2px solid #FFFFFF" : "2px solid transparent",
                    opacity: selected ? 1 : 0.88,
                  }}
                  className="rounded-sm px-2 py-1.5 text-center"
                >
                  <div className="text-[11px] font-semibold leading-tight">{b.range}</div>
                </button>
              );
            })}
          </div>
          <button
            onClick={confirmName}
            disabled={!nameInput.trim() || !bracketDraft}
            style={{
              background: (!nameInput.trim() || !bracketDraft) ? COLORS.panelAlt : COLORS.amber,
              color: (!nameInput.trim() || !bracketDraft) ? COLORS.textFaint : "#1B1030",
              cursor: (!nameInput.trim() || !bracketDraft) ? "default" : "pointer",
            }}
            className="w-full rounded-sm py-2 text-sm font-semibold uppercase tracking-wide"
          >
            Enter Room
          </button>
        </div>
      </div>
    );
  }

  const localNow = new Date(now.getTime() + tzOffset * 60000);
  const changeViewMode = (mode) => { setViewMode(mode); saveTzPrefs(tzOffset, mode); };
  const changeTz = (minutes) => { setTzOffset(minutes); saveTzPrefs(minutes, viewMode); };

  return (
    <div style={{ background: viewMode === "local" ? COLORS.bgLocal : COLORS.bg, minHeight: "100vh", color: COLORS.textPrimary, fontFamily: "'JetBrains Mono', monospace", transition: "background 0.2s ease" }}>
      <style>{FONT_IMPORT}{`
        @keyframes pulseRow { 0%,100% { opacity: 0.55; } 50% { opacity: 1; } }
        ::-webkit-scrollbar { width: 6px; height: 6px; }
        ::-webkit-scrollbar-thumb { background: ${COLORS.border}; border-radius: 4px; }
        select.war-room-select { color-scheme: dark; }
        select.war-room-select option { background: ${COLORS.panelAlt}; color: ${COLORS.textPrimary}; }
      `}</style>

      {/* header */}
      <div style={{ borderBottom: `1px solid ${COLORS.border}`, background: COLORS.panel }} className="px-4 py-3 sticky top-0 z-20">
        <div className="flex items-center justify-between gap-3">
          <div className="flex items-center gap-2 min-w-0">
            <img src={KRAKEN_LOGO} alt="Kraken" style={{ width: 30, height: 30, borderRadius: "50%", flexShrink: 0 }} />
            <div className="min-w-0">
              <div style={{ fontFamily: "'Oswald', sans-serif", letterSpacing: "0.08em" }} className="uppercase text-sm font-semibold leading-none">Kraken's War Room</div>
              <div style={{ color: COLORS.textFaint }} className="text-[10px] uppercase tracking-wide mt-0.5">Joint Availability · Faction Ops</div>
            </div>
          </div>
          <div className="text-right shrink-0">
            <div className="flex items-center gap-1 justify-end" style={{ color: COLORS.red, animation: "pulseRow 1.6s ease-in-out infinite" }}>
              <Clock3 size={13} />
              <span className="text-xs font-medium">{pad2(now.getUTCHours())}:{pad2(now.getUTCMinutes())} TCT</span>
            </div>
            <div className="flex items-center gap-1 justify-end mt-0.5">
              <span style={{ color: COLORS.textMuted }} className="text-[11px] font-medium">{pad2(localNow.getUTCHours())}:{pad2(localNow.getUTCMinutes())}</span>
              <select
                value={tzOffset}
                onChange={(e) => changeTz(Number(e.target.value))}
                style={{ background: COLORS.panelAlt, border: `1px solid ${COLORS.border}`, color: COLORS.textMuted, colorScheme: "dark" }}
                className="war-room-select rounded-sm px-1 py-0.5 text-[10px]"
              >
                {TZ_OPTIONS.map((opt) => (
                  <option key={opt.minutes} value={opt.minutes}>{opt.label}</option>
                ))}
              </select>
            </div>
            <button
              onClick={() => setEditingBracket((v) => !v)}
              style={{ background: bracketFor(myBracket).bg, color: bracketFor(myBracket).text }}
              className="text-[10px] mt-0.5 rounded-sm px-1.5 py-0.5 font-semibold"
              title="Tap to change your bracket"
            >
              {name}
            </button>
          </div>
        </div>
        {editingBracket && (
          <div style={{ background: COLORS.panelAlt, border: `1px solid ${COLORS.border}` }} className="rounded-sm p-2 mt-2 grid grid-cols-3 gap-1.5">
            {BRACKETS.map((b) => (
              <button
                key={b.key}
                onClick={() => changeBracket(b.key)}
                style={{
                  background: b.bg,
                  color: b.text,
                  border: myBracket === b.key ? "2px solid #FFFFFF" : "2px solid transparent",
                }}
                className="rounded-sm px-1.5 py-1 text-center"
              >
                <div className="text-[10px] font-semibold leading-tight">{b.range}</div>
              </button>
            ))}
          </div>
        )}
        <div className="flex items-center gap-1 mt-2 justify-end">
          <button
            onClick={() => changeViewMode("tct")}
            style={{
              background: viewMode === "tct" ? COLORS.amber : "transparent",
              color: viewMode === "tct" ? "#1B1030" : COLORS.textMuted,
              border: `1px solid ${viewMode === "tct" ? COLORS.amber : COLORS.border}`,
            }}
            className="rounded-sm px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide"
          >
            Torn Time
          </button>
          <button
            onClick={() => changeViewMode("local")}
            style={{
              background: viewMode === "local" ? COLORS.amber : "transparent",
              color: viewMode === "local" ? "#1B1030" : COLORS.textMuted,
              border: `1px solid ${viewMode === "local" ? COLORS.amber : COLORS.border}`,
            }}
            className="rounded-sm px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide"
          >
            My Time
          </button>
        </div>
      </div>

      <div className="max-w-3xl mx-auto p-3 md:p-4">
        {/* day tabs */}
        <div className="flex items-center gap-2 mb-3">
          <div className="flex items-center gap-1 overflow-x-auto pb-1 min-w-0">
            <button onClick={() => setDayIdx((d) => Math.max(0, d - 1))} disabled={dayIdx === 0}
              style={{ color: dayIdx === 0 ? COLORS.textFaint : COLORS.textMuted }} className="p-1 shrink-0">
              <ChevronLeft size={16} />
            </button>
            {days.map((d, i) => {
              const lbl = dayLabel(d);
              const active = i === dayIdx;
              return (
                <button
                  key={i}
                  onClick={() => setDayIdx(i)}
                  style={{
                    background: active ? COLORS.amber : COLORS.panel,
                    color: active ? "#1B1030" : COLORS.textMuted,
                    border: `1px solid ${active ? COLORS.amber : COLORS.border}`,
                  }}
                  className="shrink-0 rounded-sm px-2.5 py-1.5 text-center min-w-[56px]"
                >
                  <div className="text-[9px] uppercase tracking-wide opacity-80">{lbl.top}</div>
                  <div className="text-xs font-semibold">{lbl.bottom}</div>
                </button>
              );
            })}
            <button onClick={() => setDayIdx((d) => Math.min(DAY_COUNT - 1, d + 1))} disabled={dayIdx === DAY_COUNT - 1}
              style={{ color: dayIdx === DAY_COUNT - 1 ? COLORS.textFaint : COLORS.textMuted }} className="p-1 shrink-0">
              <ChevronRight size={16} />
            </button>
          </div>
        </div>

        {/* error strip — only rendered when there's an actual error */}
        {(saveFailed || syncFailed) && (
          <div style={{ background: COLORS.redSoft, border: `1px solid ${COLORS.red}`, color: COLORS.red }} className="rounded-sm px-3 py-2 mb-3 text-[11px]">
            <div>⚠ {saveFailed ? "your last change didn't save" : "sync failed"} — check connection</div>
            {saveErrorDetail && <div style={{ opacity: 0.85 }} className="mt-1 break-words">{saveErrorDetail}</div>}
          </div>
        )}

        {/* quick add range */}
        <div style={{ background: COLORS.panel, border: `1px solid ${COLORS.border}` }} className="rounded-sm px-3 py-2.5 mb-3">
          <div style={{ color: COLORS.textFaint }} className="text-[10px] uppercase tracking-wide mb-2">Quick add range ({viewMode === "local" ? "your time" : "TCT"})</div>
          <div className="flex flex-wrap items-center gap-2">
            <select value={rangeStart} onChange={(e) => setRangeStart(Number(e.target.value))}
              style={{ background: COLORS.panelAlt, border: `1px solid ${COLORS.border}`, color: COLORS.textPrimary, colorScheme: "dark" }}
              className="war-room-select rounded-sm px-2 py-1 text-xs">
              {Array.from({ length: TOTAL_SLOTS }, (_, i) => (
                <option key={i} value={i} disabled={isToday && i < nowSlot}>
                  {viewMode === "local" ? localLabel(i, tzOffset).time : slotTime(i)}{isToday && i < nowSlot ? " (past)" : ""}
                </option>
              ))}
            </select>
            <span style={{ color: COLORS.textFaint }} className="text-xs">to</span>
            <select value={rangeEnd} onChange={(e) => setRangeEnd(Number(e.target.value))}
              style={{ background: COLORS.panelAlt, border: `1px solid ${COLORS.border}`, color: COLORS.textPrimary, colorScheme: "dark" }}
              className="war-room-select rounded-sm px-2 py-1 text-xs">
              {Array.from({ length: TOTAL_SLOTS + 1 }, (_, i) => (
                <option key={i} value={i}>
                  {i === TOTAL_SLOTS ? (viewMode === "local" ? localLabel(TOTAL_SLOTS, tzOffset).time : "24:00") : (viewMode === "local" ? localLabel(i, tzOffset).time : slotTime(i))}
                </option>
              ))}
            </select>
            <button
              onClick={() => rangeEnd > rangeStart && applyRange(name, currentDateKey, rangeStart, rangeEnd, true)}
              style={{ background: COLORS.amber, color: "#1B1030" }}
              className="flex items-center gap-1 rounded-sm px-2.5 py-1 text-xs font-semibold"
            >
              <Plus size={12} /> mark free
            </button>
            <button
              onClick={() => clearDay(name, currentDateKey)}
              disabled={mySet.size === 0}
              style={{
                background: COLORS.panelAlt,
                color: mySet.size === 0 ? COLORS.textFaint : COLORS.textMuted,
                border: `1px solid ${COLORS.border}`,
                opacity: mySet.size === 0 ? 0.6 : 1,
                cursor: mySet.size === 0 ? "default" : "pointer",
              }}
              className="flex items-center gap-1 rounded-sm px-2.5 py-1 text-xs"
            >
              <Trash2 size={12} /> clear day
            </button>
          </div>
        </div>

        <div className="grid md:grid-cols-[1fr_200px] gap-3">
          {/* grid */}
          <div style={{ background: COLORS.panel, border: `1px solid ${COLORS.border}` }} className="rounded-sm overflow-hidden">
            <div style={{ borderBottom: `1px solid ${COLORS.border}`, color: COLORS.textFaint }} className="px-3 py-1.5 text-[10px] uppercase tracking-wide flex justify-between">
              <span>Time ({viewMode === "local" ? "Your Time" : "TCT"})</span>
              <span>{isCoarsePointer ? "tap to toggle" : "click or drag to toggle"}</span>
            </div>
            <div style={{ maxHeight: "60vh", overflowY: "auto" }} className="select-none">
              {Array.from({ length: TOTAL_SLOTS }, (_, idx) => {
                const c = counts.arr[idx];
                const intensity = totalOperatives > 0 ? Math.min(c / Math.max(totalOperatives, 1), 1) : 0;
                const mine = mySet.has(idx);
                const isNow = isToday && idx === nowSlot;
                const bg = c === 0 ? COLORS.panel : mixHex(COLORS.panel, COLORS.accent, 0.18 + intensity * 0.55);
                const strongFill = intensity > 0.4;
                const timeColor = isNow ? COLORS.red : strongFill ? COLORS.textPrimary : COLORS.textMuted;
                const who = counts.who[idx] || [];
                const notesHere = counts.notesByIdx[idx] || {};
                const isPast = isToday && idx < nowSlot;
                const local = viewMode === "local" ? localLabel(idx, tzOffset) : null;
                const primaryTime = local ? local.time : slotTime(idx);
                const isEditingHere = noteEditor && noteEditor.idx === idx;
                return (
                  <div key={idx} ref={isNow ? nowRowRef : null}>
                    <div
                      onClick={() => !isPast && onCellClick(idx)}
                      onPointerDown={() => !isPast && onCellDown(idx)}
                      onPointerEnter={() => !isPast && onCellEnter(idx)}
                      style={{
                        background: bg,
                        opacity: isPast ? 0.45 : 1,
                        borderBottom: who.length > 0 ? "none" : `1px solid ${COLORS.borderSoft}`,
                        borderLeft: mine ? `3px solid ${COLORS.amber}` : "3px solid transparent",
                        cursor: isPast ? "default" : "pointer",
                      }}
                      className="flex items-center justify-between px-3 py-1.5 text-xs"
                    >
                      <span className="flex items-center gap-2">
                        <span style={{ color: timeColor, animation: isNow ? "pulseRow 1.6s ease-in-out infinite" : "none" }} className="font-medium w-14">
                          {primaryTime}
                          {local && local.dayShift !== 0 && (
                            <sup style={{ color: COLORS.textFaint }}>{local.dayShift > 0 ? "+1" : "-1"}</sup>
                          )}
                        </span>
                        {local && <span style={{ color: COLORS.textFaint }} className="text-[9px]">TCT {slotTime(idx)}</span>}
                        {mine && <span style={{ color: "#FFFFFF" }} className="text-[9px] uppercase tracking-wide font-semibold">{name}</span>}
                      </span>
                      <span style={{ color: strongFill ? COLORS.textPrimary : c > 0 ? COLORS.textMuted : COLORS.textFaint }} className="text-[11px]">
                        {isPast ? (c > 0 ? `${c} was free` : "past") : c > 0 ? `${c} free` : "—"}
                      </span>
                    </div>
                    {who.length > 0 && (
                      <div
                        style={{ background: COLORS.panelAlt, borderBottom: `1px solid ${COLORS.borderSoft}`, color: COLORS.textMuted, opacity: isPast ? 0.45 : 1 }}
                        className="px-3 py-1 pl-[60px] text-[10px] flex flex-wrap gap-x-2 gap-y-1 items-center"
                      >
                        {who.map((u) => {
                          const ub = bracketFor(allAvail[u] && allAvail[u]._bracket);
                          return (
                            <span
                              key={u}
                              onClick={(e) => {
                                if (u !== name) return;
                                e.stopPropagation();
                                setNoteEditor({ idx, text: notesHere[u] || "" });
                              }}
                              style={{
                                color: ub.text,
                                background: ub.bg,
                                border: u === name ? "2px solid #FFFFFF" : "2px solid transparent",
                                padding: "1px 6px",
                                borderRadius: "10px",
                                fontWeight: u === name ? 700 : 500,
                                cursor: u === name ? "pointer" : "default",
                              }}
                              title={u === name ? "Tap to add/edit a note" : undefined}
                            >
                              {u}
                              {notesHere[u] && <span style={{ fontStyle: "italic", opacity: 0.85 }}> — {notesHere[u]}</span>}
                              {u === name && !notesHere[u] && <span style={{ opacity: 0.8 }}> ✎</span>}
                            </span>
                          );
                        })}
                      </div>
                    )}
                    {isEditingHere && (
                      <div
                        onClick={(e) => e.stopPropagation()}
                        style={{ background: COLORS.panelAlt, borderBottom: `1px solid ${COLORS.borderSoft}` }}
                        className="px-3 py-1.5 pl-[60px] flex items-center gap-2"
                      >
                        <input
                          autoFocus
                          value={noteEditor.text}
                          placeholder="e.g. only one phone"
                          maxLength={140}
                          onChange={(e) => setNoteEditor({ idx, text: e.target.value })}
                          onKeyDown={(e) => {
                            if (e.key === "Enter") { setNote(name, currentDateKey, idx, noteEditor.text); setNoteEditor(null); }
                            if (e.key === "Escape") setNoteEditor(null);
                          }}
                          onBlur={() => { setNote(name, currentDateKey, idx, noteEditor.text); setNoteEditor(null); }}
                          style={{ background: COLORS.panel, border: `1px solid ${COLORS.border}`, color: COLORS.textPrimary }}
                          className="flex-1 rounded-sm px-2 py-1 text-[11px] outline-none"
                        />
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          </div>

          {/* roster */}
          <div style={{ background: COLORS.panel, border: `1px solid ${COLORS.border}` }} className="rounded-sm p-3 h-fit">
            <div style={{ color: COLORS.textFaint }} className="text-[10px] uppercase tracking-wide mb-2">Roster — this day</div>
            {roster.length === 0 && <div style={{ color: COLORS.textFaint }} className="text-xs">No one has logged in yet.</div>}
            <div className="space-y-2">
              {roster.map((u) => {
                const n = normalizeDay(allAvail[u] && allAvail[u][currentDateKey]).slots.length;
                const pct = Math.min(n / TOTAL_SLOTS, 1);
                const ub = bracketFor(allAvail[u] && allAvail[u]._bracket);
                return (
                  <div key={u}>
                    <div className="flex justify-between text-[11px] mb-0.5">
                      <span style={{ color: ub.bg, fontWeight: u === name ? 700 : 500 }}>{u}{u === name ? " (you)" : ""}</span>
                      <span style={{ color: COLORS.textFaint }}>{n ? `${(n * 0.5).toFixed(1)}h` : "—"}</span>
                    </div>
                    <div style={{ background: COLORS.panelAlt }} className="h-1 rounded-full overflow-hidden">
                      <div style={{ width: `${pct * 100}%`, background: ub.bg }} className="h-full" />
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        </div>

        <div style={{ color: COLORS.textFaint }} className="text-[10px] mt-3 pb-4 text-center">
          All times shown in TCT (UTC), matching Torn's clock. Data is shared live with everyone using this room.
        </div>
      </div>
    </div>
  );
}
